      const lamps = new THREE.InstancedMesh(lampGeo, lampMat, PARAMS.LAMPS);
      lamps.name = "lamps" + i;
      for (let k = 0; k < PARAMS.LAMPS; k++) lamps.setMatrixAt(k, polar(PARAMS.LAMP_R, D.ANGLE + TAU * (k + 0.5) / PARAMS.LAMPS, 0.02));
      lamps.setColorAt(0, new THREE.Color(1, 1, 1));
