    sphere(leafB, 0.022, xf(leafW - 0.05, PARAMS.GATE.POST_H * 0.55, 0.025), C.gold, 6, 4);
    sphere(leafB, 0.022, xf(leafW - 0.05, PARAMS.GATE.POST_H * 0.55, -0.025), C.gold, 6, 4);
    const doorMesh = inst(leafB.build(), paint2Mat, (PARAMS.FLOORS + 1) * 2, "doors");
    const doors = [];
