    chest.add(lid);
    const tdB = new Builder();
    const sp = (r, x, y, z, c, sx, sy, sz) => tdB.add(new THREE.SphereGeometry(r, r > 0.06 ? low ? 8 : 12 : 6, r > 0.06 ? low ? 6 : 8 : 4), xf(x, y, z, 0, 0, sx || 1, sy || 1, sz || 1), c);
